+pub(crate) fn dialog_gcd_compare_bits_for_step(step: usize, active_width: usize) -> usize {
+    let global = dialog_gcd_compare_bits().min(active_width);
+    if dialog_gcd_pa9024_compare_schedule_enabled() {
+        let scheduled = (DIALOG_GCD_PA9024_COMPARE_SCHEDULE
+            .get(step)
+            .copied()
+            .unwrap_or(global)
+            + dialog_gcd_pa9024_compare_schedule_margin())
+        .max(dialog_gcd_pa9024_compare_schedule_floor())
+        .min(active_width);
+        return scheduled.min(global).max(1);
+    }
+    global.max(1)

+    if strip_enabled {
+        let mut post_strip_fanout_passes = 0usize;
+        loop {
+            match single_ccx_fanout::rewrite_first_target_fanout(ops.clone(), 96) {
+                Ok((rewritten, witness)) => {
+                    post_strip_fanout_passes += 1;
+                    eprintln!(
+                        "POST_STRIP_TARGET_FANOUT_WITNESS: pass={} first={} blocker={} second={} controls=({}, {}) old_target={} new_target={} condition={}",
+                        post_strip_fanout_passes,
+                        witness.first_index,
+                        witness.blocker_index,
+                        witness.second_index,
+                        witness.control_a,
+                        witness.control_b,
+                        witness.old_target,
+                        witness.new_target,
+                        witness.condition,
+                    );
+                    ops = rewritten;
+                }
+                Err(error) => {
+                    eprintln!(
+                        "POST_STRIP_TARGET_FANOUT_DONE: passes={} terminal={}",
+                        post_strip_fanout_passes,
+                        error,
+                    );
+                    break;
+                }
+            }
+        }
+        assert_eq!(
+            post_strip_fanout_passes,
+            10,
+            "3701581 post-strip target-fanout census drift"
+        );
